/* Breaks the linked pieces apart: pushes each one out from their middle (smaller pieces faster), spins it and sheds
   dust.
   Adapted from Lombyte's project (GPL-3.0) for PAL by OpenRAC's tools/port.py: src/overlays/l06/gameplay/entities/002fd1a0.c, FUN_L06_00303b68. */
void break_apart_shuttle_linked_mobys(struct Moby *moby) {
    struct BreakApartShuttleLinkedMobysVars *vars = (struct BreakApartShuttleLinkedMobysVars *)moby->pvars;
    float center[4];
    float middle[4];
    float push[4];
    float spin[4];
    float pos[4];
    float vel[4];
    float accel[4];
    struct Moby *piece;
    short *list;
    short count;
    int id;
    int i;
    float largest;
    u8 *particle;
    *(u128_04FA8 *)center = 0;
    center[0] = 426.0f;
    center[1] = 189.75f;
    center[2] = 173.07f;
    spawn_timed_projected_sprite_effect(center, scale_ticks((*(int *)&blarg_explosion_flash_ticks_r)),
                                        (*(int *)&blarg_explosion_flash_color_a_r),
                                        (*(int *)&blarg_explosion_flash_color_b_r));
    largest = 0.0f;
    clear_u64_value(middle);
    list = blarg_moby_groups[vars->unk_CC];
    count = 0;
    do {
        id = *list & 0x7FFF;
        random_vector(push, 1.0f, 2.0f);
        spawn_shuttle_explosion_effect(30.0f, moby, &((struct Moby *)(level_mobys_q + (id << 8)))->pos, push, 1);
        FastVecAdd(middle, middle, &((struct Moby *)(level_mobys_q + (id << 8)))->pos);
        count++;
        if (largest < ((struct Moby *)((id << 8) + (int)level_mobys_q))->bsphere.w) {
            largest = ((struct Moby *)((id << 8) + (int)level_mobys_q))->bsphere.w;
        }
    } while (*list++ >= 0);
    FastVecScale(middle, middle, 1.0f / IntToFloat(count));
    list = blarg_moby_groups[vars->unk_CC];
    do {
        float speed;
        id = *list & 0x7FFF;
        FastVecSub(push, &((struct Moby *)(level_mobys_q + (id << 8)))->pos, middle);
        piece = (struct Moby *)((id << 8) + (int)level_mobys_q);
        speed = g_frame_time * 30.0f;
        vec_scale_to_length(push, push, -((piece->bsphere.w - largest) / largest) * speed + speed);
        push[3] = 6.0f;
        random_vector(spin, g_frame_time * 0.2617994f, g_frame_time * 0.08726646f);
        begin_moby_linear_and_angular_motion((char *)(level_mobys_q + (id << 8)), push, spin);
        for (i = 0; i < (shuttle_breakup_particles_per_piece_gp); i++) {
            piece = (struct Moby *)((id << 8) + (int)level_mobys_q);
            random_vector(pos, 0.0f, piece->bsphere.w * 0.00048828125f);
            FastVecAdd(pos, pos, &((struct Moby *)(level_mobys_q + (id << 8)))->pos);
            random_vector(vel, 0.0f, (shuttle_breakup_particle_max_speed_gp)*g_frame_time);
            clear_u64_value(accel);
            vel[3] = random_float_between((shuttle_breakup_particle_velocity_w_random_bound_a_gp),
                                          (shuttle_breakup_particle_velocity_w_random_bound_b_gp));
            accel[3] = random_float_between((shuttle_breakup_particle_acceleration_w_random_bound_a_gp),
                                            (shuttle_breakup_particle_acceleration_w_random_bound_b_gp));
            particle = PartType02Spawn(
                pos, vel, accel,
                FastTweenColor((shuttle_breakup_particle_first_color_blend_a_gp),
                               (shuttle_breakup_particle_first_color_blend_b_gp), random_float_between(0.0f, 1.0f)),
                FastTweenColor((shuttle_breakup_particle_second_color_blend_a_gp),
                               (shuttle_breakup_particle_second_color_blend_b_gp), random_float_between(0.0f, 1.0f)),
                truncate_float_to_s32(multiply_global_factor(
                    (float)(shuttle_breakup_particle_timing_random_span_frames_gp)*random_float_between(0.0f, 1.0f) +
                    1.0f)),
                truncate_float_to_s32(multiply_global_factor(
                    (float)(shuttle_breakup_particle_timing_base_a_frames_gp) *
                    (random_float_between(-(shuttle_breakup_particle_timing_variation_fraction_gp),
                                          (shuttle_breakup_particle_timing_variation_fraction_gp)) +
                     1.0f))),
                truncate_float_to_s32(multiply_global_factor(
                    (float)(shuttle_breakup_particle_timing_base_b_frames_gp) *
                    (random_float_between(-(shuttle_breakup_particle_timing_variation_fraction_gp),
                                          (shuttle_breakup_particle_timing_variation_fraction_gp)) +
                     1.0f))),
                (shuttle_breakup_particle_table_index_and_flags_gp));
            if (particle != 0) {
                particle[9] = truncate_float_to_s32(4.0f) - 0x20;
            }
        }
    } while (*list++ >= 0);
    ((struct Moby *)((id << 8) + (int)level_mobys_q))->command = 30;
}

