/* The electric fence across a ledge (class 1123): waits for its partner, animates four ribbons of arcs, then bursts
   into particles once switched off. */
void switchable_beam_barrier_update(char *moby) {
    Data_305E38 *d = ((Data_305E38 *)((Moby *)moby)->pvars);
    union {
        float tmp[30][4];
        struct {
            float a[16];
            float b[16];
            float pos[4];
            float vel[4];
        } m;
    } u;

    switch ((unsigned char)*(char *)&((struct Moby *)moby)->state) {
        case 0:
            ((Moby *)moby)->scale =
                *(float *)(*(char **)&((struct Moby *)moby)->pclass + 0x24) * vector_stream_moby_scale_multiplier_gp;
            vector_stream_fade_ticks = 0x16;
            vector_stream_regen_ticks = 0x2D;
            d->timer[1] = 0xB;
            d->timer[2] = 0x17;
            d->timer[3] = 0x22;
            d->timer[0] = 0;
            d->f18 = -1;
            if (d->f10 != -1) {
                ((struct Moby *)moby)->state = 1;
                *(int *)&((Moby *)moby)->collision = 0;
            } else {
                ((struct Moby *)moby)->state = 2;
            }
            break;
        case 1: {
            char *e = level_mobys_q + (d->f10 << 8);
            if (*(short *)(e + 0xA6) == 0x463 && (unsigned char)e[0x20] < 3) {
                return;
            }
            ((struct Moby *)moby)->state = 2;
            *(int *)&((Moby *)moby)->collision = *(int *)(*(char **)&((struct Moby *)moby)->pclass + 0x10);
            break;
        }
        case 2: {
            float f20;
            float f21;
            float v;
            int i;
            int j;
            int k;
            int l;

            if (voice_is_playing(moby, d->f18) == 0) {
                d->f18 = Moby_PlaySound_r2(0, 4, moby);
            }
            test_moby_vector_stream_collision_lines((char *)&((struct Moby *)moby)->bsphere);
            v = vector_stream_uv_scroll + vector_stream_phase_rate_gp * g_frame_time;
            vector_stream_uv_scroll = v;
            if (1.0f < v) {
                vector_stream_uv_scroll = v - 1.0f;
            }
            f21 = vector_stream_x_extent_gp / 30.0f;
            f20 = -(vector_stream_x_extent_gp * 0.5f);
            for (i = 0; i < 4; i++) {
                if (d->timer[i] == 0) {
                    for (j = 0; j < 30; j++) {
                        set_vec_to_origin_point(d->a[i][j]);
                        d->a[i][j][0] = f20;
                        random_vector(u.tmp[j], 0.0f, vector_stream_increment_random_scale_bound_gp * g_frame_time);
                        f20 += f21;
                    }
                    for (k = 1; k < 29; k++) {
                        FastVecAdd(d->b[i][k], u.tmp[k - 1], u.tmp[k]);
                        FastVecAdd(d->b[i][k], d->b[i][k], u.tmp[k + 1]);
                        FastVecScale(d->b[i][k], d->b[i][k], 0.333f);
                    }
                    d->timer[i] = vector_stream_regen_ticks;
                } else {
                    for (l = 1; l < 29; l++) {
                        FastVecAdd(d->a[i][l], d->a[i][l], d->b[i][l]);
                    }
                    d->timer[i]--;
                }
            }
            if (fast_vec_dist(&((struct Moby *)moby)->pos, blarg_camera_pos) < 48.0f) {
                AddDrawCallback((int)draw_moby_vector_streams, moby);
            }
            if (d->f14 >= 0 && *(unsigned char *)(level_mobys_q + 0xBC + (d->f14 << 8)) != 0) {
                int h;
                *(int *)&((Moby *)moby)->collision = 0;
                ((struct Moby *)moby)->state = 3;
                h = d->f18;
                if (h != -1) {
                    char *e = voice_pool + h * 0x70;
                    if (*(char **)(e + 0x88) == moby && *(unsigned char *)(e + 0x74) != 0) {
                        Sound_StopSlot(h);
                    }
                }
                d->f18 = -1;
                Moby_PlaySound(1, 0, moby);
            }
            break;
        }
        case 3: {
            int i;
            int j;

            euler_to_matrix(u.m.a, &((struct Moby *)moby)->rot.x);
            set_scale_matrix(u.m.b, vector_stream_matrix_scale);
            multiply_matrix(u.m.a, u.m.a, u.m.b);
            for (i = 0; i < 4; i++) {
                euler_to_matrix(u.m.b, &l06_vector_stream_copy_rotations[i * 4]);
                multiply_matrix(u.m.b, u.m.a, u.m.b);
                FastVecAdd(u.m.b + 12, u.m.b + 12, &((struct Moby *)moby)->pos);
                u.m.b[14] += (float)i * 1.7f + 0.6f;
                u.m.b[15] = 1.0f;
                for (j = 0; j < 50; j++) {
                    int color;
                    float scale;
                    int s;
                    unsigned char life;
                    vec_scale_to_length(u.m.pos, u.m.b, randf_sym(0.0f, vector_stream_x_extent_gp * 0.75f));
                    FastVecAdd(u.m.pos, u.m.pos, u.m.b + 12);
                    color = FastTweenColor(vector_stream_burst_color_blend_a_gp, vector_stream_burst_color_blend_b_gp,
                                           random_float_between(0.0f, 1.0f));
                    scale = random_float_between(vector_stream_burst_min_particle_scale_gp,
                                                 vector_stream_burst_max_particle_scale_gp);
                    s = truncate_float_to_s32(random_float_between((float)vector_stream_burst_min_lifetime_frames_gp,
                                                                   (float)vector_stream_burst_max_lifetime_frames_gp));
                    random_vector(u.m.vel, vector_stream_burst_velocity_random_scale_bound_a_gp * g_frame_time,
                                  vector_stream_burst_velocity_random_scale_bound_b_gp * g_frame_time);
                    life = scale_ticks(s);
                    spawn_moving_hero_relative_alpha_fade_particle(u.m.pos, u.m.vel, color, scale, life,
                                                                   (unsigned char)random_integer_below(0xFF), 0);
                }
            }
            ((struct Moby *)moby)->state = 4;
            break;
        }
    }
}
